import 'package:cloud_firestore/cloud_firestore.dart'; import 'package:flutter/material.dart'; class BannersAdminPage extends StatelessWidget{const BannersAdminPage({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Banner Promo')),floatingActionButton:FloatingActionButton(onPressed:() async=>FirebaseFirestore.instance.collection('banners').add({'title':'Promo Baru','active':true,'createdAt':FieldValue.serverTimestamp()}),child:const Icon(Icons.add)),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('banners').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d)=>ListTile(title:Text(d.data()['title']??'Banner'),trailing:Switch(value:d.data()['active']??true,onChanged:(v)=>d.reference.update({'active':v})))).toList());}));}